import React from "react";
import { mount } from "enzyme";
import ExternalLink from "../../../../src/components/views/elements/ExternalLink";

describe("ExternalLink", () => {
    it("opens in a new tab with a descriptive screen reader cue and decorative icon", () => {
        const link = mount(<ExternalLink href="https://example.org" className="custom" data-testid="hosting">
            Upgrade to your own domain
        </ExternalLink>);
        const anchor = link.find("a");

        expect(anchor.prop("href")).toBe("https://example.org");
        expect(anchor.prop("target")).toBe("_blank");
        expect(anchor.prop("rel")).toBe("noreferrer noopener");
        expect(anchor.hasClass("mx_ExternalLink")).toBe(true);
        expect(anchor.hasClass("custom")).toBe(true);
        expect(anchor.prop("data-testid")).toBe("hosting");
        expect(anchor.text()).toContain("Upgrade to your own domain");
        expect(link.find(".mx_ExternalLink_newTabHint").text()).toBe("Opens in a new tab");
        expect(link.find(".mx_ExternalLink_icon").prop("aria-hidden")).toBe("true");
    });

    it("honors a caller's target and does not announce a new tab for same-tab links", () => {
        const link = mount(<ExternalLink href="https://example.org" target="_self">Example</ExternalLink>);

        expect(link.find("a").prop("target")).toBe("_self");
        expect(link.find(".mx_ExternalLink_newTabHint").exists()).toBe(false);
    });
});

